import{_ as r,C as n,o as i,c as o,j as t,a as s,E as l,a5 as p}from"./chunks/framework.DNkHA0lr.js";const k=JSON.parse('{"title":"心智极简主义 —— 停止思考。开始行动。","description":"","frontmatter":{"title":"心智极简主义 —— 停止思考。开始行动。","originalTitle":"Mental Minimalism – Stop Thinking. Start Doing.","date":"2022-02-23","originalUrl":"https://thedankoe.com/letters/mental-minimalism-stop-thinking-start-doing/","minutes":6,"sourceHash":"123535d0d1030e91d5f5d4e93d70737ba267bac209f0be5f7d5a186d71d90685","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/mental-minimalism-stop-thinking-start-doing/"}]]},"headers":[],"relativePath":"letters/mental-minimalism-stop-thinking-start-doing.md","filePath":"letters/mental-minimalism-stop-thinking-start-doing.md"}'),m={name:"letters/mental-minimalism-stop-thinking-start-doing.md"};function h(d,e,c,g,u,_){const a=n("ArticleMeta");return i(),o("div",null,[e[0]||(e[0]=t("h1",{id:"心智极简主义-——-停止思考。开始行动。",tabindex:"-1"},[s("心智极简主义 —— 停止思考。开始行动。 "),t("a",{class:"header-anchor",href:"#心智极简主义-——-停止思考。开始行动。","aria-label":'Permalink to "心智极简主义 —— 停止思考。开始行动。"'},"​")],-1)),l(a),e[1]||(e[1]=p('<p><a href="https://open.spotify.com/embed/episode/0hlU9i5WwSnlGTW8I0SEA0?si=1slSSCX0TSWyKVL-faK9Gw&amp;utm_source=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>有一个我们不断重演的压倒性问题。它让我陷入无限的自我怀疑，结果却发现，质疑本身就是问题所在。解决这个终极问题的办法，就是不去赋予它生命。</p><p>我说的问题就是思考。脑海里的喋喋不休。</p><p>按照灵修者和哲学家的核心教诲——我们必须学会让头脑安静下来。</p><p>“让头脑安静”似乎不太切实际。就好像它会阻碍我们在现实世界中取得物质进步。我不这么认为。</p><p>原因如下：</p><h3 id="前言" tabindex="-1"><strong>前言</strong> <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;**前言**&quot;">​</a></h3><p>在这封信中，我会大量谈论<em>思考</em>（<em>thinking</em>）。<em>大多数</em>时候，我指的是无意识的思考。也就是那些你并未<em>察觉</em>的反应、认同、偏见、信念和负面能量。你可以把这看作是我在区分纯粹的思考和带有目的的思考。有意识的思考。思考你的思考是有意识的，意味着你的临在（presence）与觉知。然而……我依然认为，即使是有意识的思考也应该有所节制。</p><h2 id="抗拒现实" tabindex="-1"><strong>抗拒现实</strong> <a class="header-anchor" href="#抗拒现实" aria-label="Permalink to &quot;**抗拒现实**&quot;">​</a></h2><p>我听过的生产力建议越多，我就越意识到人们正试图逃离自然的心流（flow）。用蛮力而非顺流而下。上周这让我陷入了深深的沉思。我生命中最高产的时刻是：</p><ol><li>遵循我的直觉和好奇心</li><li>做出“全力以赴”的有意识决定</li><li>拥有与挑战相匹配的经验</li><li>对项目的执行有清晰的认知</li><li>保持势头直到完成</li></ol><p><a href="https://youtu.be/mZDAx8-iCY4?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">我并_不_需要所有的生产力技巧和建议来榨取3-4小时的工作时间</a>。有时甚至能工作12个小时并彻夜不眠。当这种情况发生时，你无法把我从工作中拉开。工作变成了比我能参与的任何其他活动都更“好玩”的游戏。没有任何事物能阻止我把脑海中的想法变成现实。</p><p>这是高度契合（alignment）的结果。一切都水到渠成。突然就“通了”。神经化学物质构成的激情魔药涌入你的大脑。一切都变得清晰明了，你开始朝着微观愿景执行。</p><p>期间没有任何抗拒。没有任何“犹豫不决”。事情就这样自然而然地发生了，因为它本该发生。通过在宏观层面对精通与精进的追求——我的大脑向每天从眼前溜走的无限机遇敞开了大门。在那些无限的机遇中，有一个引起了我的注意。它提高了我的多巴胺水平，向我发出应该去追求它的信号，于是我照做了。没有思考。没有杂念。没有任何小我（ego）、限制性信念或过度分析导致的瘫痪（paralysis by analysis）能有机会阻挡我。</p><p>有人把这称为神圣的灵感。我很赞同这个说法。当你通过不思考与本源（Source）相连时，你就会顺应你的达摩之道（Dharmic path）去行动。也就是你的天命。你的才华会浮现，你会在行动中培养出力量。</p><p>这并没有抹杀现代生产力技巧的实用性。这是对带来指数级增长的多个生命周期的观察。构建你的工作结构是有价值的，但如果我说当我试图强求时我的工作质量更高，那我绝对是在撒谎。</p><h3 id="心智极简主义" tabindex="-1"><strong>心智极简主义</strong> <a class="header-anchor" href="#心智极简主义" aria-label="Permalink to &quot;**心智极简主义**&quot;">​</a></h3><p>这一切的目标，是帮助你理解心理时间（psychological time）的概念。也就是过去、现在和未来。一旦开始思考，你就会被割裂。你的肉体处于当下，但你的心智却停留在熟悉的过去或可预测的未来。这就是所有被感知到的问题存在的地方。我们之所以会重演同样的痛苦和负面体验，是因为它们令人熟悉。我们以前经历过它们。这引发了负面的反应、偏见和信念。因此——在这种情况下——思考应当在你目前的最佳能力范围内受到节制，并通过终生实践进一步将其最小化。</p><p>在最理想的情况下，我们不会想太多。几乎完全不思考。但社会的结构体系要求我们必须思考并接受教育，才能在这个系统内运转。心理时间会让你沦为这个系统的奴隶。多亏了互联网，这种状态还在不断延续。心理健康问题正处于历史最高点。思考与行动必须达到平衡。</p><p><em>注意：阅读、写作、社交、倾听和创造与思考并不能画等号。事实上，思考往往会剥夺这些体验的质量。当你和别人交谈时，你是否投入到了当下？还是因为在脑子里制造问题而阻碍了深度连接？</em></p><p>我们必须进行战略性思考。我们必须通过<a href="https://twitter.com/thedankoe/status/1464263989270089730?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">创造力层级（The Creation Hierarchy）</a>来框定我们的专注点。通过写下你的愿景、目标、价值观和优先事项——你的潜意识就会随之跟进。当你投入当下时，你会自然而然地朝着积极的方向移动。这就是视觉化、自我肯定以及其他结构化思考方法变得有用的地方。</p><p>它们不仅可以用来接入一个<em>潜在</em>（而非可预测）未来的能量，还消除了去思考“哪些机会与你契合”的需要。它们是你记忆中的一个锚点，能让模式识别发挥作用。你会（从一种兴奋的感觉中）知道自己应该追求什么。</p><p>重申一次，这些也应该有所节制。思考是一个工具，而不是主人。行动应该占据你一天中的大部分时间，处于一种无念（no-mind）的状态。主动唤醒你的感官。<a href="https://youtu.be/-UqRnWKL2Hc?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">对当下的深度感到敬畏。</a>在对话中全神贯注地倾听。在伴侣身边全心全意地去感受。感知你周围的空间。与我们本源（Source）辐射出的正能量相连接。</p><p>要明白，你不需要为了<em>做</em>而去<em>思考</em>。思考常常会降低做事的质量。当你与无限智慧（Infinite Intelligence）——所有知识的根源——相连时，你就不需要思考了，而现代社会正是建立在这些知识之上，并将其反过来用来对付我们的。</p><h3 id="心流公式" tabindex="-1"><strong>心流公式</strong> <a class="header-anchor" href="#心流公式" aria-label="Permalink to &quot;**心流公式**&quot;">​</a></h3><p>当你框定了自己的专注点，意味着你可以少想一些，你就创造了进入心流（flow）状态的潜能。与生活同流，而不是抗拒它。你可以进入的心流是有层次的。当下一刻让你立即接触到某种程度的心流。创造的行为则让你进入更深层次的心流。根据我过往的经验和研究，以下这些因素必须同时发挥作用。</p><p><strong>1) 好奇心（Curiosity）</strong> —— 你必须保持开放，并密切关注那些吸引并保持你注意力、且与你兴趣相符的事物。</p><p><strong>2) 目标（Objective）</strong> —— 一个从短期到长期的目标、项目或愿景。把它写下来并时刻提醒自己，但不要过度思考。达成这个目标的挑战难度应当略高于你当前的技能水平。</p><p><strong>3) 清晰度（Clarity）</strong> —— 通向愿景的目标，以及达成目标的任务。如果你不确定该采取哪些步骤——你必须去自我教育。通过互联网去学习。</p><p><strong>4) 意图（Intention）</strong> —— 你正在努力向什么方向拓展自己。你在向目标所呈现的挑战拓展。</p><p><strong>5) 行动（Action）</strong> —— 简化的行动。不要去想第一步之后的事。带着（由前述步骤产生的）灵感迈出第一步。</p><p>这些都隐含在创造力层级之中。如果你已经将其部署到位，你就不需要做太多思考。早晚的提醒、反思和优化就能解决问题。</p><p>就在这里收尾吧。</p><p>祝周末愉快，我的朋友们，</p><p>Dan Koe</p><hr><p><a href="/en/letters/mental-minimalism-stop-thinking-start-doing">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',37))])}const b=r(m,[["render",h]]);export{k as __pageData,b as default};
